def get_inspection_latitude(request):
    latitude = clean_optional_decimal(request.POST.get("photo_latitude"))
    if latitude is None or latitude < Decimal("-90") or latitude > Decimal("90"):
        return None
    return latitude


def get_inspection_longitude(request):
    longitude = clean_optional_decimal(request.POST.get("photo_longitude"))
    if longitude is None or longitude < Decimal("-180") or longitude > Decimal("180"):
        return None
    return longitude


def stamp_location_on_photo(uploaded_file, latitude, longitude):
    if latitude is None or longitude is None:
        return uploaded_file

    try:
        uploaded_file.seek(0)
        image = Image.open(uploaded_file)
        image = ImageOps.exif_transpose(image).convert("RGB")

        draw = ImageDraw.Draw(image)
        font = ImageFont.load_default(size=max(18, image.width // 45))
        text = f"Lat: {latitude}  Long: {longitude}"
        text_bbox = draw.textbbox((0, 0), text, font=font)
        text_height = text_bbox[3] - text_bbox[1]
        padding = max(12, image.width // 80)
        strip_height = text_height + (padding * 2)
        y1 = image.height - strip_height

        draw.rectangle([(0, y1), (image.width, image.height)], fill=(0, 0, 0))
        draw.text((padding, y1 + padding), text, fill=(255, 255, 255), font=font)

        output = BytesIO()
        image_format = "JPEG"
        filename = uploaded_file.name
        if filename.lower().endswith(".png"):
            image_format = "PNG"
        image.save(output, format=image_format, quality=90)
        output.seek(0)

        return ContentFile(output.read(), name=filename)
    except Exception:
        uploaded_file.seek(0)
        return uploaded_file


def api_login_required(view_func):
    def wrapper(request, *args, **kwargs):
        if not request.user.is_authenticated:
            return JsonResponse({"error": "Unauthorized"}, status=401)
        return view_func(request, *args, **kwargs)
    return wrapper


def get_land_record_api_headers():
    key = (
        os.getenv('7_12_key')
        or os.getenv('SEVEN_TWELVE_KEY')
        or os.getenv('LAND_RECORD_API_KEY')
    )
    if not key:
        return {}
    return {'X-Internal-Auth': key.strip()}

def normalize_match_text(value):
    return re.sub(r'\s+', ' ', str(value or '')).strip().casefold()


def normalize_gut_value(value):
    devanagari_digits = ''.join(chr(code) for code in range(0x0966, 0x0970))
    ascii_digits = '0123456789'
    normalized = str(value or '').translate(str.maketrans(devanagari_digits, ascii_digits))
    numbers = re.findall(r'\d+', normalized)
    return '/'.join(numbers) if numbers else clean_optional_char(value)

def fetch_valid_gut_map_for_location(district_name, taluka_name, village_name):
    """
    Return mapping:
      normalize_gut_value(system_gut_name) -> system_gut_name
    using the same gut DB source as dropdown location API.
    """
    if not district_name or not taluka_name or not village_name:
        return {}
    with connection.cursor() as cursor:
        cursor.execute("""
            SELECT DISTINCT e.gut_no::text
            FROM purandar_airport.prj_district a
            JOIN purandar_airport.prj_taluka c ON a.district_id = c.district_id
            JOIN purandar_airport.prj_village d ON c.taluka_id = d.taluka_id
            JOIN purandar_airport.prj_gut_bd e ON d.village_id = e.village_id
            LEFT JOIN public.district_master dm ON a.district_id = dm.id
            LEFT JOIN public.taluka_master tm ON c.taluka_id = tm.id
            LEFT JOIN public.village_master vm ON d.village_id = vm.id
            WHERE (
                    UPPER(TRIM(a.name)) = UPPER(TRIM(%s))
                    OR UPPER(TRIM(COALESCE(dm.district_name_m, ''))) = UPPER(TRIM(%s))
                  )
              AND (
                    UPPER(TRIM(c.taluka)) = UPPER(TRIM(%s))
                    OR UPPER(TRIM(COALESCE(tm.taluka_name_m, ''))) = UPPER(TRIM(%s))
                  )
              AND (
                    UPPER(TRIM(d.village)) = UPPER(TRIM(%s))
                    OR UPPER(TRIM(COALESCE(vm.village_name_m, ''))) = UPPER(TRIM(%s))
                  )
              AND e.gut_no IS NOT NULL
            ORDER BY e.gut_no::text
        """, [district_name, district_name, taluka_name, taluka_name, village_name, village_name])
        gut_values = [str(row[0]).strip() for row in cursor.fetchall() if str(row[0] or '').strip()]

    valid_gut_map = {}
    for system_gut_name in gut_values:
        gut_key = normalize_gut_value(system_gut_name)
        if gut_key and gut_key not in valid_gut_map:
            valid_gut_map[gut_key] = system_gut_name
    return valid_gut_map


def format_gut_number_for_storage(value):
    """
    Preserve descriptive gut text when present, but add a Marathi gut prefix
    for plain numeric inputs so stored values match list display expectations.
    """
    text = str(value or '').strip()
    if not text:
        return ''

    normalized = normalize_match_text(text)
    if normalized in {'', '-', 'na', 'n/a'}:
        return ''

    # Keep already-labeled values untouched (e.g., "à¤—à¤Ÿ à¤¨à¤‚.109", "Gut No. 109").
    if any(token in normalized for token in ('à¤—à¤Ÿ', 'gut', 'survey', 'à¤¸à¤°à¥à¤µà¥‡')):
        return text

    # For numeric-style values from parser (e.g., "109", "109/1"), apply prefix.
    if re.fullmatch(r'[\d\s./-]+', text):
        compact = re.sub(r'\s+', '', text)
        return f'\u0917\u091f \u0928\u0902.{compact}'

    return text


def resolve_project_table_name(cursor, *table_candidates, schemas=("purandar_airport", "purandar_airport")):
    for schema_name in schemas:
        for table_name in table_candidates:
            cursor.execute(
                """
                SELECT 1
                FROM information_schema.tables
                WHERE table_schema = %s
                  AND table_name = %s
                LIMIT 1;
                """,
                [schema_name, table_name],
            )
            if cursor.fetchone():
                return f"{schema_name}.{table_name}"
    return None

def build_location_aliases(district, taluka, village):
    """
    Build normalized aliases (English + Marathi) for a selected location.
    This allows matching rows that may come in either language.
    """
    aliases = {
        'district': set(),
        'taluka': set(),
        'village': set(),
    }

    if district:
        aliases['district'].add(normalize_match_text(district))
    if taluka:
        aliases['taluka'].add(normalize_match_text(taluka))
    if village:
        aliases['village'].add(normalize_match_text(village))

    try:
        with connection.cursor() as cursor:
            cursor.execute("""
                SELECT
                    a.name,
                    COALESCE(NULLIF(dm.district_name_m, ''), ''),
                    c.taluka,
                    COALESCE(NULLIF(tm.taluka_name_m, ''), ''),
                    d.village,
                    COALESCE(NULLIF(vm.village_name_m, ''), '')
                FROM purandar_airport.prj_district a
                JOIN purandar_airport.prj_taluka c
                    ON a.district_id = c.district_id
                JOIN purandar_airport.prj_village d
                    ON c.taluka_id = d.taluka_id
                LEFT JOIN public.district_master dm
                    ON a.district_id = dm.id
                LEFT JOIN public.taluka_master tm
                    ON c.taluka_id = tm.id
                LEFT JOIN public.village_master vm
                    ON d.village_id = vm.id
                WHERE
                    (UPPER(TRIM(a.name)) = UPPER(TRIM(%s))
                     OR UPPER(TRIM(dm.district_name_m)) = UPPER(TRIM(%s)))
                    AND (UPPER(TRIM(c.taluka)) = UPPER(TRIM(%s))
                         OR UPPER(TRIM(tm.taluka_name_m)) = UPPER(TRIM(%s)))
                    AND (UPPER(TRIM(d.village)) = UPPER(TRIM(%s))
                         OR UPPER(TRIM(vm.village_name_m)) = UPPER(TRIM(%s)))
            """, [district, district, taluka, taluka, village, village])

            for row in cursor.fetchall():
                aliases['district'].update(
                    normalize_match_text(v) for v in (row[0], row[1]) if v
                )
                aliases['taluka'].update(
                    normalize_match_text(v) for v in (row[2], row[3]) if v
                )
                aliases['village'].update(
                    normalize_match_text(v) for v in (row[4], row[5]) if v
                )
    except Exception:
        # Fall back to user-selected values only.
        pass

    return aliases

def resolve_location_to_english(district, taluka, village):
    """
    Resolve a location entered in English or Marathi to canonical English names.
    Returns (district, taluka, village); falls back to original values if not found.
    """
    district = (district or '').strip()
    taluka = (taluka or '').strip()
    village = (village or '').strip()
    if not (district and taluka and village):
        return district, taluka, village

    try:
        with connection.cursor() as cursor:
            cursor.execute("""
                SELECT
                    a.name AS district_en,
                    c.taluka AS taluka_en,
                    d.village AS village_en
                FROM purandar_airport.prj_district a
                JOIN purandar_airport.prj_taluka c
                    ON a.district_id = c.district_id
                JOIN purandar_airport.prj_village d
                    ON c.taluka_id = d.taluka_id
                LEFT JOIN public.district_master dm
                    ON a.district_id = dm.id
                LEFT JOIN public.taluka_master tm
                    ON c.taluka_id = tm.id
                LEFT JOIN public.village_master vm
                    ON d.village_id = vm.id
                WHERE
                    (UPPER(TRIM(a.name)) = UPPER(TRIM(%s))
                     OR UPPER(TRIM(COALESCE(dm.district_name_m, ''))) = UPPER(TRIM(%s)))
                    AND (UPPER(TRIM(c.taluka)) = UPPER(TRIM(%s))
                         OR UPPER(TRIM(COALESCE(tm.taluka_name_m, ''))) = UPPER(TRIM(%s)))
                    AND (UPPER(TRIM(d.village)) = UPPER(TRIM(%s))
                         OR UPPER(TRIM(COALESCE(vm.village_name_m, ''))) = UPPER(TRIM(%s)))
                LIMIT 1
            """, [district, district, taluka, taluka, village, village])
            row = cursor.fetchone()
            if row:
                return (row[0] or district, row[1] or taluka, row[2] or village)
    except Exception:
        pass

    return district, taluka, village

def text_matches_aliases(value, aliases, normalizer=normalize_match_text):
    normalized_value = normalizer(value)
    if not normalized_value:
        return False
    for alias in aliases:
        if alias and (alias in normalized_value or normalized_value in alias):
            return True
    return False

