def parse_land_record_712_html(request):
    def fix_encoding(text):
        try:
            return text.encode('latin1').decode('utf-8')
        except Exception:
            return text

    def row_get(row, *keys):
        for key in keys:
            value = row.get(key)
            if value is not None and str(value).strip() != '':
                return fix_encoding(str(value).strip())
        return ''

    def detect_file_type(filename):
        name = (filename or '').lower()
        if name.endswith(('.html', '.htm')):
            return 'html'
        if name.endswith(('.xlsx', '.xls')):
            return 'excel'
        return None

    district = (request.POST.get('district') or '').strip()
    taluka = (request.POST.get('taluka') or '').strip()
    village = (request.POST.get('village') or '').strip()
    gut_number = format_gut_number_for_storage(request.POST.get('gut_number'))
    uploaded_file = request.FILES.get('document_712')

    if not uploaded_file:
        return JsonResponse({'success': False, 'error': 'Please choose a file.'}, status=400)

    upload_mode = detect_file_type(uploaded_file.name)
    if not upload_mode:
        return JsonResponse({'success': False, 'error': 'Supported files: .html, .htm, .xlsx, .xls'}, status=400)

    api_url = os.getenv(
        'LAND_RECORD_UPLOAD_API_URL',
        'http://209.182.233.103:8005/api/upload-land-record/'
    )

    try:
        uploaded_file.seek(0)
        ext = os.path.splitext(uploaded_file.name.lower())[1]
        if ext in ('.html', '.htm'):
            content = uploaded_file.read().decode('utf-8', errors='ignore').encode('utf-8')
            mime_type = 'text/html'
        elif ext == '.xlsx':
            content = uploaded_file.read()
            mime_type = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
        else:
            content = uploaded_file.read()
            mime_type = 'application/vnd.ms-excel'

        response = requests.post(
            api_url,
            files={'file': (uploaded_file.name, content, mime_type)},
            headers=get_land_record_api_headers(),
            timeout=60
        )
        response.raise_for_status()
        payload = json.loads(response.content.decode('utf-8'))
    except requests.RequestException:
        return JsonResponse({'success': False, 'error': 'Service is not working.'}, status=502)
    except ValueError:
        return JsonResponse({'success': False, 'error': '7/12 API did not return valid JSON.'}, status=502)

    eligible_rows = payload.get('eligible', []) or []
    not_eligible_rows = payload.get('not_eligible', []) or []
    rows = [*eligible_rows, *not_eligible_rows]
    if not rows:
        return JsonResponse({'success': False, 'error': 'No record found in uploaded file.'}, status=400)

    kul_khand_info = ''
    kul_token = '\u0915\u0941\u0933'
    for key, value in payload.items():
        key_text = str(key or '')
        if (kul_token in key_text or 'kul' in key_text.casefold()) and isinstance(value, str):
            kul_khand_info = fix_encoding(value)
            break

    location_aliases = build_location_aliases(district, taluka, village)
    records = []
    for row in rows:
        row_district = row_get(row, '\u091c\u093f\u0932\u094d\u0939\u093e', 'district')
        row_taluka = row_get(row, '\u0924\u093e\u0932\u0941\u0915\u093e', 'taluka')
        row_village = row_get(row, '\u0917\u093e\u0935\u093e\u091a\u0947 \u0928\u093e\u0935', '\u0917\u093e\u0935', 'village', 'village_name')
        if upload_mode == 'excel' and all([district, taluka, village]):
            district_matches = text_matches_aliases(row_district, location_aliases['district'])
            taluka_matches = text_matches_aliases(row_taluka, location_aliases['taluka'])
            village_matches = text_matches_aliases(row_village, location_aliases['village'])
            if not (district_matches and taluka_matches and village_matches):
                continue
        raw_gut = row_get(
            row,
            '\u0917\u091f \u0928\u0902\u092c\u0930/\u0938\u0930\u094d\u0935\u0947 \u0928\u0902\u092c\u0930',
            '\u0917\u091f \u0928\u0902\u092c\u0930',
            '\u0938\u0930\u094d\u0935\u0947 \u0928\u0902\u092c\u0930',
            'gut_number',
            'gutnumber',
            'survey_no'
        )
        excel_gut_key = normalize_gut_value(raw_gut)
        if not excel_gut_key:
            continue
        records.append({
            'district': row_district or district,
            'taluka': row_taluka or taluka,
            'village': row_village or village,
            'gut_number': format_gut_number_for_storage(raw_gut),
            'original_excel_gut': raw_gut,
            'excel_gut_key': excel_gut_key,
            'khata_number': row_get(row, '\u0916\u093e\u0924\u093e_\u0928\u0902', '\u0916\u093e\u0924\u093e \u0928\u0902', '\u0916\u093e\u0924\u093e \u0928\u0902\u092c\u0930', 'khata_number'),
            'puid_ulip_no': row_get(row, 'PUID_ULIP_No', 'puid_ulip_no'),
            'jirayit': row_get(row, '\u091c\u093f\u0930\u093e\u092f\u0924', 'jirayit'),
            'bagayat': row_get(row, '\u092c\u093e\u0917\u093e\u092f\u0924', 'bagayat'),
            'potkharaba': row_get(row, '\u092a\u094b\u091f\u0916\u0930\u093e\u092c', 'potkharaba'),
            'total_area': row_get(row, '\u090f\u0915\u0942\u0923_\u0915\u094d\u0937\u0947\u0924\u094d\u0930', '\u090f\u0915\u0942\u0923 \u0915\u094d\u0937\u0947\u0924\u094d\u0930', 'total_area'),
            'aakarni': row_get(row, '\u0906\u0915\u093e\u0930\u0923\u0940', 'aakarni'),
            'khata_area': row_get(row, '\u0916\u093e\u0924\u093e_\u0915\u094d\u0937\u0947\u0924\u094d\u0930', '\u0916\u093e\u0924\u093e \u0915\u094d\u0937\u0947\u0924\u094d\u0930', 'khata_area'),
            'aakar': row_get(row, '\u0906\u0915\u093e\u0930', 'aakar'),
            'holder_name': clean_holder_name_list(row_get(row, '\u092d\u094b\u0917\u0935\u091f\u093e\u0926\u093e\u0930\u093e\u091a\u0947 \u0928\u093e\u0902\u0935', '\u092d\u094b\u0917\u0935\u091f\u093e\u0926\u093e\u0930\u093e\u091a\u0947 \u0928\u093e\u0935', 'holder_name', 'ownername')),
            'kul_khand_other_rights': row_get(row, '\u0915\u0941\u0933, \u0916\u0902\u0921 \u0935 \u0907\u0924\u0930 \u0905\u0927\u093f\u0915\u093e\u0930', 'kul_khand_other_rights') or kul_khand_info,
            'area_more_than_20guntha': row_get(row, '\u0915\u094d\u0937\u0947\u0924\u094d\u0930_20_\u0917\u0941\u0902\u0920\u0947_\u092a\u0947\u0915\u094d\u0937\u093e_\u091c\u093e\u0938\u094d\u0924', 'area_more_than_20guntha'),
            'bagayat_more_than_10guntha': row_get(row, '\u092c\u093e\u0917\u093e\u092f\u0924_10_\u0917\u0941\u0902\u0920\u0947_\u092a\u0947\u0915\u094d\u0937\u093e_\u091c\u093e\u0938\u094d\u0924', 'bagayat_more_than_10guntha'),
        })
    if upload_mode == 'excel' and all([district, taluka, village]) and not records:
        return JsonResponse({
            'success': False,
            'error': 'Selected location and uploaded file location are not matching.'
        }, status=400)

    if not records:
        return JsonResponse({'success': False, 'error': 'No record found in uploaded file.'}, status=400)

    first = next((r for r in records if r.get('district') and r.get('taluka') and r.get('village')), {})
    district_candidates = [r.get('district', '').strip() for r in records if r.get('district')]
    taluka_candidates = [r.get('taluka', '').strip() for r in records if r.get('taluka')]
    village_candidates = [r.get('village', '').strip() for r in records if r.get('village')]
    gut_candidates = [format_gut_number_for_storage(r.get('gut_number', '')) for r in records if r.get('gut_number')]

    def most_common(items):
        normalized = [str(item or '').strip() for item in items if str(item or '').strip()]
        if not normalized:
            return ''
        return Counter(normalized).most_common(1)[0][0]

    detected_district = district or most_common(district_candidates) or first.get('district', '') or ''
    detected_taluka = taluka or most_common(taluka_candidates) or first.get('taluka', '') or ''
    detected_village = village or most_common(village_candidates) or first.get('village', '') or ''
    detected_gut = gut_number or most_common(gut_candidates) or format_gut_number_for_storage(first.get('gut_number', ''))
    detected_district, detected_taluka, detected_village = resolve_location_to_english(
        detected_district, detected_taluka, detected_village
    )

    valid_gut_map = fetch_valid_gut_map_for_location(detected_district, detected_taluka, detected_village)
    unmatched_guts = set()
    for row in records:
        if not row.get('district'):
            row['district'] = detected_district
        if not row.get('taluka'):
            row['taluka'] = detected_taluka
        if not row.get('village'):
            row['village'] = detected_village
        excel_gut_key = normalize_gut_value(row.get('gut_number'))
        matched_system_gut = valid_gut_map.get(excel_gut_key, '')
        is_matched = bool(matched_system_gut)
        row['matched_system_gut'] = matched_system_gut
        row['matched_gut_name'] = matched_system_gut
        row['match_status'] = 'Matched' if is_matched else 'Unmatched'
        row['gut_match_status'] = row['match_status']
        if is_matched:
            row['gut_number'] = matched_system_gut
            row['is_gut_matched'] = True
        else:
            row['is_gut_matched'] = False
            unmatched_guts.add(row.get('original_excel_gut') or row.get('gut_number') or '')

    detected_location = {
        'district': detected_district,
        'taluka': detected_taluka,
        'village': detected_village,
        'gut_number': detected_gut,
    }
    preview_token = _land_record_712_store_preview_payload(
        request=request,
        records=records,
        location=detected_location,
        file_type=upload_mode,
        original_document_name=uploaded_file.name,
    )
    first_page = _land_record_712_get_preview_page(records, page=1, page_size=25)

    return JsonResponse({
        'success': True,
        'records': first_page['records'],
        'count': first_page['total_count'],
        'file_type': upload_mode,
        'location': detected_location,
        'unmatched_guts': sorted([g for g in unmatched_guts if g]),
        'preview_token': preview_token,
        'preview': {
            'page': first_page['page'],
            'page_size': first_page['page_size'],
            'total_pages': first_page['total_pages'],
            'total_count': first_page['total_count'],
        },
    })


@login_required
@require_http_methods(["GET"])
def land_record_712_preview_page(request):
    preview_token = (request.GET.get('preview_token') or '').strip()
    if not preview_token:
        return JsonResponse({'success': False, 'error': 'Missing preview token.'}, status=400)

    try:
        page = int(request.GET.get('page', 1))
    except (TypeError, ValueError):
        page = 1
    try:
        page_size = int(request.GET.get('page_size', 25))
    except (TypeError, ValueError):
        page_size = 25

    search_query = (request.GET.get('q') or request.GET.get('query') or '').strip()
    def normalize_preview_search_text(value):
        value = str(value or '')
        devanagari_digits = ''.join(chr(code) for code in range(0x0966, 0x0970))
        value = value.translate(str.maketrans(devanagari_digits, '0123456789'))
        return value.strip().lower()
    search_query = normalize_preview_search_text(search_query)

    preview_payload = _land_record_712_get_preview_payload(request, preview_token)
    if not preview_payload:
        return JsonResponse({'success': False, 'error': 'Upload preview expired. Please re-upload the file.'}, status=404)

    records = preview_payload.get('records') or []
    if search_query:
        def record_matches(record):
            haystack = ' '.join(
                str(record.get(key, '') or '')
                for key in [
                    'original_excel_gut', 'raw_gut_number', 'gut_number',
                    'khata_number', 'holder_name', 'puid_ulip_no',
                    'khata_area', 'total_area', 'aakar', 'aakarni'
                ]
            )
            haystack = normalize_preview_search_text(haystack)
            return search_query in haystack

        records = [record for record in records if record_matches(record)]

    page_data = _land_record_712_get_preview_page(records=records, page=page, page_size=page_size)
    return JsonResponse({
        'success': True,
        'records': page_data['records'],
        'preview': {
            'page': page_data['page'],
            'page_size': page_data['page_size'],
            'total_pages': page_data['total_pages'],
            'total_count': page_data['total_count'],
        },
    })

