def _progress_empty():
    return {
        "total": 0,
        "completed": 0,
        "draft": 0,
        "not_started": 0,
        "progress_percentage": 0,
    }


def _progress_payload(total, completed, draft):
    total = int(total or 0)
    completed = int(completed or 0)
    draft = int(draft or 0)
    not_started = max(total - completed - draft, 0)
    progress_percentage = round((completed / total) * 100) if total else 0
    return {
        "total": total,
        "completed": completed,
        "draft": draft,
        "not_started": not_started,
        "progress_percentage": progress_percentage,
    }


def _norm_scope_value(value):
    return normalize_match_text(value)


def _scope_lookup(values, key):
    return {row[key] for row in values if row.get(key)}


def _resolve_dashboard_scope(request):
    district_id = clean_optional_char(request.GET.get('district_id'))
    taluka_id = clean_optional_char(request.GET.get('taluka_id'))
    village_id = clean_optional_char(request.GET.get('village_id'))
    gut_number = clean_optional_char(request.GET.get('gut_id')) or clean_optional_char(request.GET.get('gut'))
    district_name = clean_optional_char(request.GET.get('district'))
    taluka_name = clean_optional_char(request.GET.get('taluka'))
    village_name = clean_optional_char(request.GET.get('village'))

    with connection.cursor() as cursor:
        if not district_id and district_name:
            cursor.execute("""
                SELECT district_id
                FROM purandar_airport.prj_district
                WHERE UPPER(TRIM(name)) = UPPER(TRIM(%s))
                LIMIT 1;
            """, [district_name])
            row = cursor.fetchone()
            district_id = str(row[0]) if row else ""

        if not taluka_id and taluka_name:
            cursor.execute("""
                SELECT c.taluka_id
                FROM purandar_airport.prj_taluka c
                JOIN purandar_airport.prj_district a ON a.district_id = c.district_id
                WHERE UPPER(TRIM(c.taluka)) = UPPER(TRIM(%s))
                  AND (%s = '' OR a.district_id::text = %s OR UPPER(TRIM(a.name)) = UPPER(TRIM(%s)))
                LIMIT 1;
            """, [taluka_name, district_id, district_id, district_name])
            row = cursor.fetchone()
            taluka_id = str(row[0]) if row else ""

        if not village_id and village_name:
            cursor.execute("""
                SELECT d.village_id
                FROM purandar_airport.prj_village d
                JOIN purandar_airport.prj_taluka c ON c.taluka_id = d.taluka_id
                JOIN purandar_airport.prj_district a ON a.district_id = c.district_id
                WHERE UPPER(TRIM(d.village)) = UPPER(TRIM(%s))
                  AND (%s = '' OR c.taluka_id::text = %s OR UPPER(TRIM(c.taluka)) = UPPER(TRIM(%s)))
                  AND (%s = '' OR a.district_id::text = %s OR UPPER(TRIM(a.name)) = UPPER(TRIM(%s)))
                LIMIT 1;
            """, [village_name, taluka_id, taluka_id, taluka_name, district_id, district_id, district_name])
            row = cursor.fetchone()
            village_id = str(row[0]) if row else ""

        conditions = []
        params = []
        if district_id:
            conditions.append("a.district_id::text = %s")
            params.append(district_id)
        elif district_name:
            conditions.append("UPPER(TRIM(a.name)) = UPPER(TRIM(%s))")
            params.append(district_name)

        if taluka_id:
            conditions.append("c.taluka_id::text = %s")
            params.append(taluka_id)
        elif taluka_name:
            conditions.append("UPPER(TRIM(c.taluka)) = UPPER(TRIM(%s))")
            params.append(taluka_name)

        if village_id:
            conditions.append("d.village_id::text = %s")
            params.append(village_id)
        elif village_name:
            conditions.append("UPPER(TRIM(d.village)) = UPPER(TRIM(%s))")
            params.append(village_name)

        if gut_number:
            conditions.append("UPPER(TRIM(e.gut_no::text)) = UPPER(TRIM(%s))")
            params.append(gut_number)

        where_clause = ("WHERE " + " AND ".join(conditions)) if conditions else ""
        cursor.execute(f"""
            SELECT DISTINCT
                a.name AS district,
                c.taluka AS taluka,
                d.village AS village,
                e.gut_no::text AS gut_number
            FROM purandar_airport.prj_district a
            JOIN purandar_airport.prj_taluka c ON a.district_id = c.district_id
            JOIN purandar_airport.prj_village d ON c.taluka_id = d.taluka_id
            LEFT JOIN purandar_airport.prj_gut_bd e ON d.village_id = e.village_id
            {where_clause}
            ORDER BY a.name, c.taluka, d.village, e.gut_no::text;
        """, params)

        rows = [
            {
                "district": row[0] or "",
                "taluka": row[1] or "",
                "village": row[2] or "",
                "gut_number": row[3] or "",
            }
            for row in cursor.fetchall()
        ]

    village_keys = {
        (_norm_scope_value(row["district"]), _norm_scope_value(row["taluka"]), _norm_scope_value(row["village"]))
        for row in rows
        if row["village"]
    }
    gut_keys = {
        (
            _norm_scope_value(row["district"]),
            _norm_scope_value(row["taluka"]),
            _norm_scope_value(row["village"]),
            normalize_gut_value(row["gut_number"]),
        )
        for row in rows
        if row["village"] and row["gut_number"]
    }
    return rows, village_keys, gut_keys


@api_login_required
def get_dashboard_progress(request):
    try:
        scope_rows, village_keys, gut_keys = _resolve_dashboard_scope(request)
    except Exception as exc:
        return JsonResponse({"error": str(exc)}, status=500)

    if not scope_rows:
        return JsonResponse({
            "village_info": _progress_empty(),
            "bhusampadana_prakriya": _progress_empty(),
        })

    districts = _scope_lookup(scope_rows, "district")
    talukas = _scope_lookup(scope_rows, "taluka")
    villages = _scope_lookup(scope_rows, "village")
    guts = _scope_lookup(scope_rows, "gut_number")

    village_records = VillageData.objects.all()
    if districts:
        village_records = village_records.filter(district__in=districts)
    if talukas:
        village_records = village_records.filter(taluka__in=talukas)
    if villages:
        village_records = village_records.filter(village__in=villages)

    village_status_by_key = {}
    for record in village_records.order_by('is_final_submitted', 'updated_at', 'id'):
        key = (_norm_scope_value(record.district), _norm_scope_value(record.taluka), _norm_scope_value(record.village))
        if key not in village_keys:
            continue
        previous = village_status_by_key.get(key)
        status = "completed" if record.is_final_submitted else "draft"
        if previous != "completed":
            village_status_by_key[key] = status

    village_completed = sum(1 for status in village_status_by_key.values() if status == "completed")
    village_draft = sum(1 for status in village_status_by_key.values() if status == "draft")
    village_info = _progress_payload(len(village_keys), village_completed, village_draft)

    process_records = ProcessChartCase.objects.all()
    if districts:
        process_records = process_records.filter(district__in=districts)
    if talukas:
        process_records = process_records.filter(taluka__in=talukas)
    if villages:
        process_records = process_records.filter(village__in=villages)
    if guts:
        process_records = process_records.filter(gut_number__in=guts)

    process_status_by_key = {}
    for record in process_records.order_by('status', 'updated_at', 'id'):
        key = (
            _norm_scope_value(record.district),
            _norm_scope_value(record.taluka),
            _norm_scope_value(record.village),
            normalize_gut_value(record.gut_number),
        )
        if key not in gut_keys:
            continue
        status = "completed" if record.status in ("submitted", "approved") else "draft"
        previous = process_status_by_key.get(key)
        if previous != "completed":
            process_status_by_key[key] = status

    process_completed = sum(1 for status in process_status_by_key.values() if status == "completed")
    process_draft = sum(1 for status in process_status_by_key.values() if status == "draft")
    bhusampadana_prakriya = _progress_payload(len(gut_keys), process_completed, process_draft)

    return JsonResponse({
        "village_info": village_info,
        "bhusampadana_prakriya": bhusampadana_prakriya,
    })

def _safe_schema_name(raw_schema):
    schema = clean_optional_char(raw_schema)
    if schema and re.match(r"^[A-Za-z_][A-Za-z0-9_]*$", schema):
        return schema
    return "purandar_airport"


def _as_int_or_none(value):
    try:
        return int(str(value).strip())
    except (TypeError, ValueError, AttributeError):
        return None


def _aligned_geom_expr(alias):
    return f"""
        CASE
            WHEN ST_SRID({alias}.geom) = ST_SRID(p.geom)
                 OR ST_SRID({alias}.geom) = 0
                 OR ST_SRID(p.geom) = 0
                THEN {alias}.geom
            ELSE ST_Transform({alias}.geom, ST_SRID(p.geom))
        END
    """


@api_login_required
def get_dashboard_affected_counts(request):
    project_id = _as_int_or_none(request.GET.get("project_id"))
    tenant_id = clean_optional_char(request.GET.get("tenant_id"))

    district_id = _as_int_or_none(request.GET.get("district_id"))
    taluka_id = _as_int_or_none(request.GET.get("taluka_id"))
    village_id = _as_int_or_none(request.GET.get("village_id"))
    gut_id = clean_optional_char(request.GET.get("gut_id")) or clean_optional_char(request.GET.get("gut"))

    district_name = clean_optional_char(request.GET.get("district"))
    taluka_name = clean_optional_char(request.GET.get("taluka"))
    village_name = clean_optional_char(request.GET.get("village"))

    zero_payload = {
        "affected_districts": 0,
        "affected_talukas": 0,
        "affected_villages": 0,
        "affected_guts": 0,
        "affected_area_ha": 0,
    }

    try:
        with connection.cursor() as cursor:
            project_conditions = ["geom IS NOT NULL"]
            project_params = []

            if project_id is not None:
                project_conditions.append("id = %s")
                project_params.append(project_id)
            if tenant_id:
                project_conditions.append("UPPER(COALESCE(schema_name, '')) = UPPER(%s)")
                project_params.append(tenant_id)

            cursor.execute(
                f"""
                SELECT id, COALESCE(NULLIF(schema_name, ''), 'purandar_airport') AS schema_name
                FROM public.project_master
                WHERE {' AND '.join(project_conditions)}
                ORDER BY id
                LIMIT 1;
                """,
                project_params,
            )
            project_row = cursor.fetchone()
            if not project_row:
                return JsonResponse(zero_payload)

            resolved_project_id = int(project_row[0])
            project_schema = _safe_schema_name(project_row[1])

            district_table = resolve_project_table_name(cursor, "prj_district", schemas=(project_schema, "purandar_airport"))
            taluka_table = resolve_project_table_name(cursor, "prj_taluka", schemas=(project_schema, "purandar_airport"))
            village_table = resolve_project_table_name(cursor, "prj_village", schemas=(project_schema, "purandar_airport"))
            gut_table = resolve_project_table_name(cursor, "prj_gut_bd", schemas=(project_schema, "purandar_airport"))

            if not (district_table and taluka_table and village_table):
                return JsonResponse(zero_payload)

            # Resolve IDs from names when needed.
            if district_id is None and district_name:
                cursor.execute(
                    """
                    SELECT id
                    FROM public.district_master
                    WHERE UPPER(TRIM(COALESCE(district_name, ''))) = UPPER(TRIM(%s))
                       OR UPPER(TRIM(COALESCE(district_name_m, ''))) = UPPER(TRIM(%s))
                    LIMIT 1;
                    """,
                    [district_name, district_name],
                )
                row = cursor.fetchone()
                district_id = int(row[0]) if row else None

            if taluka_id is None and taluka_name:
                params = [taluka_name, taluka_name]
                sql = """
                    SELECT id
                    FROM public.taluka_master
                    WHERE (
                        UPPER(TRIM(COALESCE(taluka_name, ''))) = UPPER(TRIM(%s))
                        OR UPPER(TRIM(COALESCE(taluka_name_m, ''))) = UPPER(TRIM(%s))
                    )
                """
                if district_id is not None:
                    sql += " AND district_id = %s"
                    params.append(district_id)
                sql += " LIMIT 1;"
                cursor.execute(sql, params)
                row = cursor.fetchone()
                taluka_id = int(row[0]) if row else None

            if village_id is None and village_name:
                params = [village_name, village_name]
                sql = """
                    SELECT id, taluka_id
                    FROM public.village_master
                    WHERE (
                        UPPER(TRIM(COALESCE(village_name, ''))) = UPPER(TRIM(%s))
                        OR UPPER(TRIM(COALESCE(village_name_m, ''))) = UPPER(TRIM(%s))
                    )
                """
                if taluka_id is not None:
                    sql += " AND taluka_id = %s"
                    params.append(taluka_id)
                sql += " LIMIT 1;"
                cursor.execute(sql, params)
                row = cursor.fetchone()
                if row:
                    village_id = int(row[0])
                    taluka_id = taluka_id or _as_int_or_none(row[1])

            if village_id is not None and taluka_id is None:
                cursor.execute("SELECT taluka_id FROM public.village_master WHERE id = %s LIMIT 1;", [village_id])
                row = cursor.fetchone()
                taluka_id = _as_int_or_none(row[0]) if row else taluka_id

            if taluka_id is not None and district_id is None:
                cursor.execute("SELECT district_id FROM public.taluka_master WHERE id = %s LIMIT 1;", [taluka_id])
                row = cursor.fetchone()
                district_id = _as_int_or_none(row[0]) if row else district_id

            invalid_location = (
                (district_name and district_id is None) or
                (taluka_name and taluka_id is None) or
                (village_name and village_id is None)
            )
            if invalid_location:
                return JsonResponse(zero_payload)

            district_filter = ""
            taluka_filter = ""
            village_filter = ""
            gut_filter = ""
            district_params = [resolved_project_id]
            taluka_params = [resolved_project_id]
            village_params = [resolved_project_id]
            gut_params = [resolved_project_id]

            if district_id is not None:
                district_filter += " AND dm.id = %s"
                taluka_filter += " AND tm.district_id = %s"
                village_filter += " AND tm.district_id = %s"
                gut_filter += " AND tm.district_id = %s"
                district_params.append(district_id)
                taluka_params.append(district_id)
                village_params.append(district_id)
                gut_params.append(district_id)

            if taluka_id is not None:
                taluka_filter += " AND tm.id = %s"
                village_filter += " AND vm.taluka_id = %s"
                gut_filter += " AND vm.taluka_id = %s"
                taluka_params.append(taluka_id)
                village_params.append(taluka_id)
                gut_params.append(taluka_id)

            if village_id is not None:
                village_filter += " AND vm.id = %s"
                gut_filter += " AND vm.id = %s"
                village_params.append(village_id)
                gut_params.append(village_id)

            if gut_id:
                gut_filter += " AND UPPER(TRIM(g.gut_no::text)) = UPPER(TRIM(%s))"
                gut_params.append(gut_id)

            district_geom = _aligned_geom_expr("dm")
            taluka_geom = _aligned_geom_expr("tm")
            village_geom = _aligned_geom_expr("vm")

            cursor.execute(
                f"""
                WITH p AS (
                    SELECT ST_MakeValid(geom) AS geom
                    FROM public.project_master
                    WHERE id = %s
                )
                SELECT COUNT(DISTINCT dm.id)
                FROM {district_table} pd
                JOIN public.district_master dm ON dm.id = pd.district_id
                CROSS JOIN p
                WHERE dm.geom IS NOT NULL
                  AND p.geom && {district_geom}
                  AND ST_Intersects(p.geom, {district_geom})
                  {district_filter};
                """,
                district_params,
            )
            affected_districts = int(cursor.fetchone()[0] or 0)

            cursor.execute(
                f"""
                WITH p AS (
                    SELECT ST_MakeValid(geom) AS geom
                    FROM public.project_master
                    WHERE id = %s
                )
                SELECT COUNT(DISTINCT tm.id)
                FROM {taluka_table} pt
                JOIN public.taluka_master tm ON tm.id = pt.taluka_id
                CROSS JOIN p
                WHERE tm.geom IS NOT NULL
                  AND p.geom && {taluka_geom}
                  AND ST_Intersects(p.geom, {taluka_geom})
                  {taluka_filter};
                """,
                taluka_params,
            )
            affected_talukas = int(cursor.fetchone()[0] or 0)

            cursor.execute(
                f"""
                WITH p AS (
                    SELECT ST_MakeValid(geom) AS geom
                    FROM public.project_master
                    WHERE id = %s
                )
                SELECT COUNT(DISTINCT vm.id)
                FROM {village_table} pv
                JOIN public.village_master vm ON vm.id = pv.village_id
                JOIN public.taluka_master tm ON tm.id = vm.taluka_id
                CROSS JOIN p
                WHERE vm.geom IS NOT NULL
                  AND p.geom && {village_geom}
                  AND ST_Intersects(p.geom, {village_geom})
                  {village_filter};
                """,
                village_params,
            )
            affected_villages = int(cursor.fetchone()[0] or 0)

            affected_guts = 0
            affected_area_ha = 0.0

            if gut_table:
                gut_geom = _aligned_geom_expr("g")

                cursor.execute(
                    f"""
                    WITH p AS (
                        SELECT ST_MakeValid(geom) AS geom
                        FROM public.project_master
                        WHERE id = %s
                    )
                    SELECT COUNT(DISTINCT g.id)
                    FROM {gut_table} g
                    JOIN public.village_master vm ON vm.id = g.village_id
                    JOIN public.taluka_master tm ON tm.id = vm.taluka_id
                    CROSS JOIN p
                    WHERE g.geom IS NOT NULL
                      AND p.geom && {gut_geom}
                      AND ST_Intersects(p.geom, {gut_geom})
                      {gut_filter};
                    """,
                    gut_params,
                )
                affected_guts = int(cursor.fetchone()[0] or 0)

                cursor.execute(
                    f"""
                    WITH p AS (
                        SELECT ST_MakeValid(geom) AS geom
                        FROM public.project_master
                        WHERE id = %s
                    ),
                    intersections AS (
                        SELECT ST_Intersection(p.geom, {gut_geom}) AS i_geom
                        FROM {gut_table} g
                        JOIN public.village_master vm ON vm.id = g.village_id
                        JOIN public.taluka_master tm ON tm.id = vm.taluka_id
                        CROSS JOIN p
                        WHERE g.geom IS NOT NULL
                          AND p.geom && {gut_geom}
                          AND ST_Intersects(p.geom, {gut_geom})
                          {gut_filter}
                    )
                    SELECT COALESCE(
                        SUM(
                            CASE
                                WHEN ST_IsEmpty(i_geom) THEN 0
                                WHEN ST_SRID(i_geom) = 4326 THEN ST_Area(i_geom::geography)
                                ELSE ST_Area(i_geom)
                            END
                        ) / 10000.0,
                        0
                    )
                    FROM intersections;
                    """,
                    gut_params,
                )
                affected_area_ha = float(cursor.fetchone()[0] or 0)

        return JsonResponse(
            {
                "affected_districts": int(affected_districts or 0),
                "affected_talukas": int(affected_talukas or 0),
                "affected_villages": int(affected_villages or 0),
                "affected_guts": int(affected_guts or 0),
                "affected_area_ha": round(float(affected_area_ha or 0), 2),
                "project_id": resolved_project_id,
                "tenant_id": tenant_id or project_schema,
            }
        )
    except OperationalError:
        return JsonResponse(zero_payload)
    except Exception as exc:
        payload = dict(zero_payload)
        if getattr(request, "user", None) and request.user.is_superuser:
            payload["error"] = str(exc)
        return JsonResponse(payload)


@api_login_required
def get_project_stats(request):
    district_id = request.GET.get('district_id')
    taluka_id = request.GET.get('taluka_id')
    village_id = request.GET.get('village_id')
    district_name = (request.GET.get('district') or '').strip() or None
    taluka_name = (request.GET.get('taluka') or '').strip() or None
    village_name = (request.GET.get('village') or '').strip() or None
    gut_number = request.GET.get('gut')

    with connection.cursor() as cursor:
        column_cache = {}

        def table_has_column(table_name, column_name):
            key = (table_name, column_name)
            if key not in column_cache:
                cursor.execute("""
                    SELECT 1
                    FROM information_schema.columns
                    WHERE table_schema = 'purandar_airport'
                      AND table_name = %s
                      AND column_name = %s
                    LIMIT 1;
                """, [table_name, column_name])
                column_cache[key] = cursor.fetchone() is not None
            return column_cache[key]

        # Resolve public master IDs when the frontend sends names instead of IDs.
        if not district_id and district_name:
            cursor.execute("""
                SELECT id
                FROM public.district_master
                WHERE UPPER(TRIM(COALESCE(district_name, ''))) = UPPER(TRIM(%s))
                   OR UPPER(TRIM(COALESCE(district_name_m, ''))) = UPPER(TRIM(%s))
                LIMIT 1;
            """, [district_name, district_name])
            row = cursor.fetchone()
            district_id = row[0] if row else None

        if not taluka_id and taluka_name and district_name:
            cursor.execute("""
                SELECT id
                FROM public.taluka_master
                WHERE (
                    district_id = %s
                    OR UPPER(TRIM(COALESCE(district, ''))) = UPPER(TRIM(%s))
                    OR UPPER(TRIM(COALESCE(district, ''))) = UPPER(TRIM(%s))
                )
                  AND (
                    UPPER(TRIM(COALESCE(taluka_name, ''))) = UPPER(TRIM(%s))
                    OR UPPER(TRIM(COALESCE(taluka_name_m, ''))) = UPPER(TRIM(%s))
                  )
                LIMIT 1;
            """, [district_id or -1, district_name, district_name, taluka_name, taluka_name])
            row = cursor.fetchone()
            taluka_id = row[0] if row else None

        if not village_id and village_name and district_name and taluka_name:
            cursor.execute("""
                SELECT id
                FROM public.village_master
                WHERE (
                    taluka_id = %s
                    OR (
                        UPPER(TRIM(COALESCE(district, ''))) = UPPER(TRIM(%s))
                        AND UPPER(TRIM(COALESCE(taluka, ''))) = UPPER(TRIM(%s))
                    )
                    OR (
                        UPPER(TRIM(COALESCE(district, ''))) = UPPER(TRIM(%s))
                        AND UPPER(TRIM(COALESCE(taluka, ''))) = UPPER(TRIM(%s))
                    )
                )
                  AND (
                    UPPER(TRIM(COALESCE(village_name, ''))) = UPPER(TRIM(%s))
                    OR UPPER(TRIM(COALESCE(village_name_m, ''))) = UPPER(TRIM(%s))
                  )
                LIMIT 1;
            """, [
                taluka_id or -1,
                district_name, taluka_name,
                district_name, taluka_name,
                village_name, village_name
            ])
            row = cursor.fetchone()
            village_id = row[0] if row else None

            if village_id is None and district_id and taluka_id:
                cursor.execute("""
                    SELECT village_id
                    FROM purandar_airport.prj_village
                    WHERE district_id = %s
                      AND taluka_id = %s
                      AND UPPER(TRIM(village)) = UPPER(TRIM(%s))
                    LIMIT 1;
                """, [district_id, taluka_id, village_name])
                row = cursor.fetchone()
                village_id = row[0] if row else None

        invalid_location = (
            (district_name and not district_id) or
            (taluka_name and not taluka_id) or
            (village_name and not village_id)
        )

        if invalid_location:
            return JsonResponse({
                "land_classification": {
                    "trees_total": 0,
                    "trees_valuation": 0,
                    "tree_categories": {},
                    "other_total": 0,
                    "other_valuation": 0,
                    "other_categories": {},
                    "structures_total": 0,
                    "structures_permanent": 0,
                    "structures_temporary": 0,
                    "structures_permanent_valuation": 0,
                    "structures_temporary_valuation": 0,
                    "structures_valuation": 0,
                    "water_total": 0,
                    "water_valuation": 0,
                }
            })

        # Build filters for asset tables (which may not always have district_id/taluka_id).
        def build_asset_filters(table_name):
            table_conditions = []
            table_params = []

            if village_id and table_has_column(table_name, 'village_id'):
                table_conditions.append("village_id = %s")
                table_params.append(village_id)
            else:
                if village_name:
                    if table_has_column(table_name, 'village') and table_has_column(table_name, 'village_m'):
                        table_conditions.append("""
                            (
                                UPPER(TRIM(COALESCE(village, ''))) = UPPER(TRIM(%s))
                                OR UPPER(TRIM(COALESCE(village_m, ''))) = UPPER(TRIM(%s))
                            )
                        """)
                        table_params.extend([village_name, village_name])
                    elif table_has_column(table_name, 'village'):
                        table_conditions.append("UPPER(TRIM(COALESCE(village, ''))) = UPPER(TRIM(%s))")
                        table_params.append(village_name)
                    elif table_has_column(table_name, 'village_m'):
                        table_conditions.append("UPPER(TRIM(COALESCE(village_m, ''))) = UPPER(TRIM(%s))")
                        table_params.append(village_name)

                if taluka_name:
                    if table_has_column(table_name, 'taluka') and table_has_column(table_name, 'taluka_m'):
                        table_conditions.append("""
                            (
                                UPPER(TRIM(COALESCE(taluka, ''))) = UPPER(TRIM(%s))
                                OR UPPER(TRIM(COALESCE(taluka_m, ''))) = UPPER(TRIM(%s))
                            )
                        """)
                        table_params.extend([taluka_name, taluka_name])
                    elif table_has_column(table_name, 'taluka'):
                        table_conditions.append("UPPER(TRIM(COALESCE(taluka, ''))) = UPPER(TRIM(%s))")
                        table_params.append(taluka_name)
                    elif table_has_column(table_name, 'taluka_m'):
                        table_conditions.append("UPPER(TRIM(COALESCE(taluka_m, ''))) = UPPER(TRIM(%s))")
                        table_params.append(taluka_name)

                if district_name:
                    if table_has_column(table_name, 'district') and table_has_column(table_name, 'district_m'):
                        table_conditions.append("""
                            (
                                UPPER(TRIM(COALESCE(district, ''))) = UPPER(TRIM(%s))
                                OR UPPER(TRIM(COALESCE(district_m, ''))) = UPPER(TRIM(%s))
                            )
                        """)
                        table_params.extend([district_name, district_name])
                    elif table_has_column(table_name, 'district'):
                        table_conditions.append("UPPER(TRIM(COALESCE(district, ''))) = UPPER(TRIM(%s))")
                        table_params.append(district_name)
                    elif table_has_column(table_name, 'district_m'):
                        table_conditions.append("UPPER(TRIM(COALESCE(district_m, ''))) = UPPER(TRIM(%s))")
                        table_params.append(district_name)

            table_where = ""
            if table_conditions:
                table_where = " AND " + " AND ".join(table_conditions)
            return table_where, table_params

        # -----------------------------
        # COMMON FILTER BUILDER
        # -----------------------------
        conditions = []
        params = []

        if district_id:
            conditions.append("district_id = %s")
            params.append(district_id)

        if taluka_id:
            conditions.append("taluka_id = %s")
            params.append(taluka_id)

        if village_id:
            conditions.append("village_id = %s")
            params.append(village_id)

        where_clause = ""
        if conditions:
            where_clause = " AND " + " AND ".join(conditions)

        # -----------------------------
        # LAND CLASSIFICATION (Asset Classification)
        # -----------------------------
        land_classification = {
            "trees_total": 0,
            "trees_valuation": 0,
            "tree_categories": {},
            "other_total": 0,
            "other_valuation": 0,
            "other_categories": {},
            "structures_total": 0,
            "structures_permanent": 0,
            "structures_temporary": 0,
            "structures_permanent_valuation": 0,
            "structures_temporary_valuation": 0,
            "structures_valuation": 0,
            "water_total": 0,
            "water_valuation": 0,
        }

        try:
            all_categories = {}

            for table in ['prj_ass_pt', 'prj_ass_pl', 'prj_ass_poly']:
                if gut_number and not table_has_column(table, 'gut_no'):
                    continue

                table_where, table_params = build_asset_filters(table)
                query = f"""
                    SELECT 
                        COALESCE(category, 'Other'),
                        COUNT(*),
                        COALESCE(SUM(
                            CASE 
                                WHEN valuation ~ '^[0-9]+\\.?[0-9]*$'
                                THEN CAST(valuation AS NUMERIC)
                                ELSE 0 
                            END
                        ), 0)
                    FROM purandar_airport.{table}
                    WHERE 1=1
                    {table_where}
                """

                cat_params = list(table_params)

                if gut_number and table_has_column(table, 'gut_no'):
                    query += " AND gut_no = %s"
                    cat_params.append(gut_number)

                query += " GROUP BY category"

                cursor.execute(query, cat_params)
                results = cursor.fetchall()

                for row in results:
                    category = row[0]
                    count = row[1]
                    valuation = float(row[2])

                    if category in all_categories:
                        all_categories[category]['count'] += count
                        all_categories[category]['valuation'] += valuation
                    else:
                        all_categories[category] = {
                            'count': count,
                            'valuation': valuation
                        }

            # Split categories
            tree_categories = {}
            other_categories = {}

            for cat, data in all_categories.items():
                if cat in ['Fruit Tree', 'Forest Tree']:
                    tree_categories[cat] = data
                else:
                    other_categories[cat] = data

            land_classification["trees_total"] = sum(c['count'] for c in tree_categories.values())
            land_classification["trees_valuation"] = sum(c['valuation'] for c in tree_categories.values())
            land_classification["tree_categories"] = tree_categories

            land_classification["other_total"] = sum(c['count'] for c in other_categories.values())
            land_classification["other_valuation"] = sum(c['valuation'] for c in other_categories.values())
            land_classification["other_categories"] = other_categories
            land_classification["structures_total"] = other_categories.get('Structure', {}).get('count', 0)
            land_classification["structures_valuation"] = other_categories.get('Structure', {}).get('valuation', 0)
            land_classification["water_total"] = other_categories.get('Other Asset', {}).get('count', 0)
            land_classification["water_valuation"] = other_categories.get('Other Asset', {}).get('valuation', 0)

        except Exception:
            pass

        # -----------------------------
        # FINAL RESPONSE
        # -----------------------------
        return JsonResponse({
            "land_classification": land_classification
        })

@api_login_required
def get_gut_numbers_by_village(request, village_name):
    """Fetch list of gut numbers for a specific village"""
    with connection.cursor() as cursor:
        try:
            cursor.execute("""
                SELECT DISTINCT gut_no
                FROM purandar_airport.prj_ass_bund_poly
                WHERE UPPER(TRIM(village)) = UPPER(TRIM(%s))
                AND gut_no IS NOT NULL
                ORDER BY gut_no;
            """, [village_name])
            gut_numbers = [row[0] for row in cursor.fetchall()]
            return JsonResponse({'gut_numbers': gut_numbers})
        except Exception as e:
            import traceback
            traceback.print_exc()
            return JsonResponse({'error': str(e), 'gut_numbers': []}, status=500)


@api_login_required
def get_layer_bounds(request, layer_name):
    """
    Returns bounding box for given layer with filters
    """

    district = request.GET.get('district')
    taluka = request.GET.get('taluka')
    village = request.GET.get('village')
    district_id = request.GET.get('district_id')
    taluka_id = request.GET.get('taluka_id')
    village_id = request.GET.get('village_id')
    gut_number = request.GET.get('gut_number')

    # Allowed layers (security)
    allowed_layers = [
        'prj_vlg_bd',
        'prj_gut_bd'
    ]

    if layer_name not in allowed_layers:
        return JsonResponse({"error": "Invalid layer"}, status=400)

    try:
        with connection.cursor() as cursor:
            conditions = []
            params = []

            if layer_name == "prj_vlg_bd":
                # Village boundary bounds: derive geometry from master villages,
                # but restrict to villages present in project table.
                if district:
                    conditions.append("UPPER(TRIM(dm.district_name)) = UPPER(TRIM(%s))")
                    params.append(district)
                if taluka:
                    conditions.append("UPPER(TRIM(tm.taluka_name)) = UPPER(TRIM(%s))")
                    params.append(taluka)
                if village:
                    conditions.append("UPPER(TRIM(vm.village_name)) = UPPER(TRIM(%s))")
                    params.append(village)
                if district_id:
                    conditions.append("pv.district_id = %s")
                    params.append(district_id)
                if taluka_id:
                    conditions.append("pv.taluka_id = %s")
                    params.append(taluka_id)
                if village_id:
                    conditions.append("pv.village_id = %s")
                    params.append(village_id)

                where_clause = f"WHERE {' AND '.join(conditions)}" if conditions else ""
                query = f"""
                    SELECT
                        ST_XMin(extent),
                        ST_YMin(extent),
                        ST_XMax(extent),
                        ST_YMax(extent)
                    FROM (
                        SELECT ST_Extent(ST_Transform(vm.geom, 4326)) AS extent
                        FROM public.village_master vm
                        JOIN purandar_airport.prj_village pv
                            ON pv.village_id = vm.id
                        JOIN public.taluka_master tm
                            ON tm.id = pv.taluka_id
                        JOIN public.district_master dm
                            ON dm.id = pv.district_id
                        {where_clause}
                    ) AS subquery;
                """
            else:
                # Gut bounds: geometry is in project gut table; use master joins
                # for name-based filters.
                if district:
                    conditions.append("UPPER(TRIM(dm.district_name)) = UPPER(TRIM(%s))")
                    params.append(district)
                if taluka:
                    conditions.append("UPPER(TRIM(tm.taluka_name)) = UPPER(TRIM(%s))")
                    params.append(taluka)
                if village:
                    conditions.append("UPPER(TRIM(vm.village_name)) = UPPER(TRIM(%s))")
                    params.append(village)
                if district_id:
                    conditions.append("pg.district_id = %s")
                    params.append(district_id)
                if taluka_id:
                    conditions.append("pg.taluka_id = %s")
                    params.append(taluka_id)
                if village_id:
                    conditions.append("pg.village_id = %s")
                    params.append(village_id)
                if gut_number:
                    conditions.append("UPPER(TRIM(pg.gut_no::text)) = UPPER(TRIM(%s))")
                    params.append(str(gut_number))

                where_clause = f"WHERE {' AND '.join(conditions)}" if conditions else ""
                query = f"""
                    SELECT
                        ST_XMin(extent),
                        ST_YMin(extent),
                        ST_XMax(extent),
                        ST_YMax(extent)
                    FROM (
                        SELECT ST_Extent(ST_Transform(pg.geom, 4326)) AS extent
                        FROM purandar_airport.prj_gut_bd pg
                        JOIN public.village_master vm
                            ON vm.id = pg.village_id
                        JOIN public.taluka_master tm
                            ON tm.id = pg.taluka_id
                        JOIN public.district_master dm
                            ON dm.id = pg.district_id
                        {where_clause}
                    ) AS subquery;
                """

            cursor.execute(query, params)
            result = cursor.fetchone()

            if result and all(value is not None for value in result):
                min_lng, min_lat, max_lng, max_lat = result
                return JsonResponse({
                    # Primary shape expected by dashboard JS
                    "bounds": {
                        "minLng": float(min_lng),
                        "minLat": float(min_lat),
                        "maxLng": float(max_lng),
                        "maxLat": float(max_lat),
                    },
                    # Backward-compatible keys
                    "xmin": float(min_lng),
                    "ymin": float(min_lat),
                    "xmax": float(max_lng),
                    "ymax": float(max_lat),
                })
            else:
                return JsonResponse({"message": "No data found"}, status=404)

    except Exception as e:
        return JsonResponse({
            "error": str(e)
        }, status=500)
    
def login_view(request):
    redirect_to = request.POST.get("next") or request.GET.get("next") or ""

    if request.method == "POST":
        username = request.POST.get("username")
        password = request.POST.get("password")

        user = authenticate(request, username=username, password=password)

        if user and user.pk:
            active_session = ActiveUserSession.objects.filter(user=user).first()
            if active_session:
                Session.objects.filter(session_key=active_session.session_key).delete()

            login(request, user)
            ActiveUserSession.objects.update_or_create(
                user=user,
                defaults={"session_key": request.session.session_key},
            )
            if redirect_to and url_has_allowed_host_and_scheme(
                url=redirect_to,
                allowed_hosts={request.get_host()},
                require_https=request.is_secure(),
            ):
                return redirect(redirect_to)
            return redirect("home")
        else:
            return render(request, "login.html", {"error": "Invalid credentials", "next": redirect_to})

    return render(request, "login.html", {"next": redirect_to})


def logout_view(request):
    if request.user.is_authenticated:
        ActiveUserSession.objects.filter(
            user=request.user,
            session_key=request.session.session_key,
        ).delete()
    logout(request)
    return redirect('login')



