@api_login_required
def get_rr_rate_by_village(request, village):
    """Return all assessment types with full rate ranges for a village (latest year)."""
    base_qs = ReadyReckonerInfo.objects.filter(village__iexact=village)
    latest_year = base_qs.order_by('-year').values_list('year', flat=True).first()
    if not latest_year:
        return JsonResponse({'found': False, 'assessment_types': []})
    qs = base_qs.filter(year=latest_year).prefetch_related('rates').order_by('assessment_type')
    types = []
    for info in qs:
        rates = [{'min': float(r.assessment_range_min), 'max': float(r.assessment_range_max), 'rate': float(r.rate)}
                 for r in info.rates.order_by('assessment_range_min')]
        if rates:
            types.append({'assessment_type': info.assessment_type, 'unit': info.unit, 'year': info.year, 'rates': rates})
    return JsonResponse({'found': bool(types), 'assessment_types': types})


@login_required
def get_village_info_data(request):
    district = (request.GET.get('district') or '').strip()
    taluka = (request.GET.get('taluka') or '').strip()
    village = (request.GET.get('village') or '').strip()

    if not district or not taluka or not village:
        return JsonResponse({'found': False, 'error': 'district, taluka and village are required'}, status=400)

    village_data = VillageData.objects.filter(
        district__iexact=district,
        taluka__iexact=taluka,
        village__iexact=village
    ).order_by('-updated_at').first()

    if not village_data:
        district_key = normalize_match_text(district)
        taluka_key = normalize_match_text(taluka)
        village_key = normalize_match_text(village)
        village_candidates = VillageData.objects.filter(village__iexact=village).order_by('-updated_at', '-id')
        for candidate in village_candidates:
            if (
                normalize_match_text(candidate.district) == district_key
                and normalize_match_text(candidate.taluka) == taluka_key
                and normalize_match_text(candidate.village) == village_key
            ):
                village_data = candidate
                break

    if not village_data:
        return JsonResponse({'found': False, 'data': None})

    data = {}
    for f in _VILLAGE_SCALAR_FIELDS:
        val = getattr(village_data, f)
        data[f] = val.isoformat() if hasattr(val, 'isoformat') and val else (val or '')
    data['sec1_admin_approvals'] = village_data.sec1_admin_approvals or []
    sec3_rows = village_data.sec3_rows or []
    if not sec3_rows:
        sec3_rows = [{
            'upvibhag_name': village_data.sec3_upvibhag_name or '',
            'officer_name': '',
            'address': '',
            'adhisuchana_kramank': village_data.sec3_adhisuchana_kramank or '',
            'date': village_data.sec3_date.isoformat() if village_data.sec3_date else '',
            'files': [],
        }]
    data['sec3_rows'] = sec3_rows
    data['sec21_rows'] = village_data.sec21_rows or []
    data['sec24_account_rows'] = village_data.sec24_account_rows or []
    data['sec25_map_rows'] = village_data.sec25_map_rows or []
    data['notified_area_rows'] = village_data.notified_area_rows or []
    data['sec1_total_notified_area'] = str(village_data.sec1_total_notified_area or 0)
    data['notified_area_totals_by_section'] = village_data.notified_area_totals_by_section or {}
    data['sec13_rows'] = village_data.sec13_rows or []
    data['sec14_rows'] = village_data.sec14_rows or []
    data['sec16_rows'] = village_data.sec16_rows or []
    data['sec17_rows'] = village_data.sec17_rows or []
    data['sec18_rows'] = village_data.sec18_rows or []
    data['sec19_rows'] = village_data.sec19_rows or []
    data['sec20_rows'] = village_data.sec20_rows or []

    # files per field_key
    files_map = {}
    for vf in village_data.village_files.all():
        files_map.setdefault(vf.field_key, []).append({'id': vf.id, 'url': vf.file.url, 'name': vf.file.name.split('/')[-1]})
    sec3_row_files_map = {}
    for key, files in files_map.items():
        m = re.match(r'^sec3_row_(\d+)$', key or '')
        if not m:
            continue
        sec3_row_files_map[int(m.group(1))] = files
    sec3_data_rows = data.get('sec3_rows') or []
    for idx, row in enumerate(sec3_data_rows):
        if not isinstance(row, dict):
            continue
        row['files'] = sec3_row_files_map.get(idx, row.get('files') or [])

    sec21_data_rows = data.get('sec21_rows') or []
    sec21_file_maps = {}
    for key, files in files_map.items():
        m = re.match(r'^sec21_row_(\d+)_(prastaav|karyavrutant)$', key or '')
        if not m:
            continue
        idx = int(m.group(1))
        bucket = m.group(2)
        sec21_file_maps.setdefault(idx, {'prastaav_files': [], 'karyavrutant_files': []})
        sec21_file_maps[idx][f'{bucket}_files'] = files
    normalized_sec21_rows = []
    for idx, row in enumerate(sec21_data_rows):
        if not isinstance(row, dict):
            row = {}
        existing_files = row.get('files') if isinstance(row.get('files'), dict) else {}
        normalized_sec21_rows.append({
            'prastaav': row.get('prastaav') or '',
            'prastaav_date': row.get('prastaav_date') or '',
            'karyavrutant': row.get('karyavrutant') or '',
            'karyavrutant_date': row.get('karyavrutant_date') or '',
            'files': {
                'prastaav_files': sec21_file_maps.get(idx, {}).get('prastaav_files', existing_files.get('prastaav_files') or []),
                'karyavrutant_files': sec21_file_maps.get(idx, {}).get('karyavrutant_files', existing_files.get('karyavrutant_files') or []),
            }
        })
    if not normalized_sec21_rows:
        normalized_sec21_rows = [{
            'prastaav': village_data.sec21_prastaav or '',
            'prastaav_date': village_data.sec21_prastaav_date.isoformat() if village_data.sec21_prastaav_date else '',
            'karyavrutant': village_data.sec21_karyavrutant or '',
            'karyavrutant_date': village_data.sec21_karyavrutant_date.isoformat() if village_data.sec21_karyavrutant_date else '',
            'files': {'prastaav_files': [], 'karyavrutant_files': []},
        }]
    data['sec21_rows'] = normalized_sec21_rows

    sec25_rows = data.get('sec25_map_rows') or []
    sec25_file_map = {}
    for key, files in files_map.items():
        m = re.match(r'^sec25_row_(\d+)$', key or '')
        if not m:
            continue
        sec25_file_map[int(m.group(1))] = files
    normalized_sec25_rows = []
    for idx, row in enumerate(sec25_rows):
        if not isinstance(row, dict):
            row = {}
        nrows = row.get('notified_rows') if isinstance(row.get('notified_rows'), list) else []
        normalized_nrows = []
        for nrow in nrows:
            if not isinstance(nrow, dict):
                continue
            normalized_nrows.append({
                'gut_number': nrow.get('gut_number') or '',
                'notified_area': nrow.get('notified_area') or '',
            })
        if not normalized_nrows:
            normalized_nrows = [{'gut_number': '', 'notified_area': ''}]
        normalized_sec25_rows.append({
            'patra_kramank': row.get('patra_kramank') or '',
            'date': row.get('date') or '',
            'notified_rows': normalized_nrows,
            'files': sec25_file_map.get(idx, row.get('files') or []),
        })
    if not normalized_sec25_rows:
        normalized_sec25_rows = [{
            'patra_kramank': village_data.sec25_kramank or '',
            'date': village_data.sec25_date.isoformat() if village_data.sec25_date else '',
            'notified_rows': [{'gut_number': '', 'notified_area': ''}],
            'files': [],
        }]
    data['sec25_map_rows'] = normalized_sec25_rows

    for sec_code, cfg in _RELATED_SECTION_ROW_CONFIG.items():
        json_field = cfg.get('json')
        if not json_field:
            continue
        section_rows = data.get(json_field) or []
        if not isinstance(section_rows, list):
            section_rows = []
        files_by_index = {}
        for key, files in files_map.items():
            m = re.match(rf'^{sec_code}_row_(\d+)$', key or '')
            if not m:
                continue
            files_by_index[int(m.group(1))] = files
        normalized_rows = []
        for idx, row in enumerate(section_rows):
            if not isinstance(row, dict):
                row = {}
            normalized_rows.append({
                'detail': row.get('detail') or '',
                'date': row.get('date') or '',
                'total_village_evaluation': row.get('total_village_evaluation') or '',
                'files': files_by_index.get(idx, row.get('files') or []),
            })
        if not normalized_rows:
            normalized_rows = [{'detail': '', 'date': '', 'total_village_evaluation': '', 'files': []}]
        data[json_field] = normalized_rows

    sec26 = []
    for row in village_data.sec26_8a_records.prefetch_related('files_8a').all():
        sec26.append({
            'id': row.id,
            'khate_kramank': row.khate_kramank,
            'navavar_kshetra': row.navavar_kshetra,
            'ferfar_kramank': row.ferfar_kramank,
            'ferfar_date': row.ferfar_date.isoformat() if row.ferfar_date else '',
            'files': [{'id': f.id, 'url': f.file.url, 'name': f.file.name.split('/')[-1]} for f in row.files_8a.all()],
        })

    sec4_rows = []
    for row in village_data.sec4_rows.prefetch_related('files_15_2').order_by('id'):
        files_by_key = {'main': [], 'paper1': [], 'paper2': []}
        for f in row.files_15_2.all():
            key = (getattr(f, 'field_key', '') or 'main').strip() or 'main'
            if key not in files_by_key:
                key = 'main'
            files_by_key[key].append({'id': f.id, 'url': f.file.url, 'name': f.file.name.split('/')[-1]})
        sec4_rows.append({
            'id': row.id,
            'adhisuchana_kramank': row.adhisuchana_kramank,
            'adhisuchana_date': row.adhisuchana_date.isoformat() if row.adhisuchana_date else '',
            'paper1_name': row.paper1_name,
            'paper1_date': row.paper1_date.isoformat() if row.paper1_date else '',
            'paper2_name': row.paper2_name,
            'paper2_date': row.paper2_date.isoformat() if row.paper2_date else '',
            'files': files_by_key,
        })

    sec8_rows = []
    for row in village_data.sec8_rows.prefetch_related('files_18_1').order_by('id'):
        files_by_key = {'main': [], 'paper1': [], 'paper2': []}
        for f in row.files_18_1.all():
            key = (getattr(f, 'field_key', '') or 'main').strip() or 'main'
            if key not in files_by_key:
                key = 'main'
            files_by_key[key].append({'id': f.id, 'url': f.file.url, 'name': f.file.name.split('/')[-1]})
        sec8_rows.append({
            'id': row.id,
            'adhisuchana_kramank': row.adhisuchana_kramank,
            'adhisuchana_date': row.adhisuchana_date.isoformat() if row.adhisuchana_date else '',
            'paper1_name': row.paper1_name,
            'paper1_date': row.paper1_date.isoformat() if row.paper1_date else '',
            'paper2_name': row.paper2_name,
            'paper2_date': row.paper2_date.isoformat() if row.paper2_date else '',
            'files': files_by_key,
        })

    sec15 = []
    for r in village_data.sec15_rates.select_related('rr_rate').all():
        sec15.append({
            'rr_rate_id': r.rr_rate_id,
            'approved_rate': float(r.approved_rate) if r.approved_rate is not None else None
        })

    return JsonResponse({
        'found': True,
        'data': data,
        'files_map': files_map,
        'sec4_rows': sec4_rows,
        'sec8_rows': sec8_rows,
        'sec26_8a_records': sec26,
        'sec15_rates': sec15
    })


@login_required
def get_village_sec15_rates(request):
    district = (request.GET.get('district') or '').strip()
    taluka = (request.GET.get('taluka') or '').strip()
    village = (request.GET.get('village') or '').strip()

    if not village:
        return JsonResponse({'found': False, 'rates': [], 'message': 'village is required'}, status=400)

    base_qs = ReadyReckonerInfo.objects.filter(village__iexact=village)
    if district:
        base_qs = base_qs.filter(district__iexact=district)
    if taluka:
        base_qs = base_qs.filter(taluka__iexact=taluka)

    latest_year = base_qs.order_by('-year').values_list('year', flat=True).first()
    if not latest_year:
        return JsonResponse({'found': False, 'rates': [], 'message': 'No ready reckoner data found for selected village'})

    village_data = VillageData.objects.filter(
        district__iexact=district,
        taluka__iexact=taluka,
        village__iexact=village
    ).order_by('-updated_at').first()
    approved_map = {}
    if village_data:
        approved_map = {
            item.rr_rate_id: float(item.approved_rate) if item.approved_rate is not None else None
            for item in village_data.sec15_rates.all()
        }

    rates_payload = []
    infos = base_qs.filter(year=latest_year).prefetch_related('rates').order_by('assessment_type')
    for info in infos:
        for rate in info.rates.order_by('assessment_range_min', 'assessment_range_max'):
            rates_payload.append({
                'rr_rate_id': rate.id,
                'assessment_type': info.assessment_type,
                'village_type': rate.village_type or 'gramin',
                'assessment_range': f"{rate.assessment_range_min} - {rate.assessment_range_max}",
                'shighrasiddha_vibhag': rate.shighrasiddha_vibhag or '',
                'ready_reckoner_rate': float(rate.rate),
                'unit': info.unit,
                'approved_rate': approved_map.get(rate.id)
            })

    return JsonResponse({
        'found': bool(rates_payload),
        'year': latest_year,
        'rates': rates_payload,
        'message': '' if rates_payload else 'No ready reckoner rates found for selected village'
    })
